-- Run this in the Athena database selected for SeaRoutes.
-- Each S3 object contains one JSON array generated by the weather Lambda.
CREATE EXTERNAL TABLE IF NOT EXISTS weather (
  records array<struct<
    timestamp:string,
    latitude:double,
    longitude:double,
    wind_speed:double,
    wind_direction:double,
    wave_height:double,
    water_temperature:double,
    air_temperature:double,
    cloud_cover:double
  >>
)
PARTITIONED BY (year string, month string, day string, hour string)
ROW FORMAT SERDE 'com.amazon.ionhiveserde.IonHiveSerDe'
WITH SERDEPROPERTIES ('ion.records.path_extractor' = '()')
STORED AS ION
LOCATION 's3://sea-routes-back/weather/';

-- Run after new date partitions are uploaded.
MSCK REPAIR TABLE weather;
